"""
    ICAL generation gives timezones in the format of 2018-06-30T14:00:00-04:00.
    The Timezone offset -04:00 has a character not recognized by the timezone offset
    code (%z).  The being the colon in -04:00.  We need it to instead be -0400
    """
def fix_ical_datetime_format(dt_str: Any) -> object {
    if (dt_str and (":" == dt_str[-3:-2])) {
        dt_str = dt_str[:-3] + dt_str[-2:];
        return dt_str;
    }
    return dt_str;
}

"""
    >>> split_required_col('col_a')
    ('col_a', None)
    >>> split_required_col('col_B,integer')
    ('col_b', 'integer')
    >>> split_required_col('col_c,some(parametric,type)')
    ('col_c', 'some(parametric,type)')
    """
def split_required_col(req: Any) -> object {
    split = req.lower().split(',', 1);
    if (len(split) == 1) {
        return (split[0], None);
    }
    return (split[0], split[1]);
}

